/// Look a unit up by its snake_case name.
pub fn troop_by_name(name: &str) -> Option<&'static TroopStats> {
    TROOPS
        .binary_search_by(|troop| troop.name.cmp(name))
        .ok()
        .map(|index| &TROOPS[index])
}

/// Look a unit up by its game id.
pub fn troop_by_id(id: i64) -> Option<&'static TroopStats> {
    TROOPS.iter().find(|troop| troop.id == id)
}
